package drone_lifecycle_governor.Drone_Lifecycle_Governor

import org.sireum._
import art._
import drone_lifecycle_governor._

// Do not edit this file as it will be overwritten if HAMR codegen is rerun

@sig trait Battery_Assessment_Api {
  def id: Art.BridgeId
  def raw_battery_Id : Art.PortId
  def battery_assessment_Id : Art.PortId

  // Logika spec var representing port state for outgoing data port
  @spec var battery_assessment: Drone_Lifecycle_Governor.Battery_Assessment_Value.Type = $

  def put_battery_assessment(value : Drone_Lifecycle_Governor.Battery_Assessment_Value.Type) : Unit = {
    Contract(
      Modifies(battery_assessment),
      Ensures(
        battery_assessment == value
      )
    )
    Spec {
      battery_assessment = value
    }

    Art.putValue(battery_assessment_Id, Drone_Lifecycle_Governor.Battery_Assessment_Value_Payload(value))
  }

  def logInfo(msg: String): Unit = {
    Art.logInfo(id, msg)
  }

  def logDebug(msg: String): Unit = {
    Art.logDebug(id, msg)
  }

  def logError(msg: String): Unit = {
    Art.logError(id, msg)
  }
}

@datatype class Battery_Assessment_Initialization_Api (
  val id: Art.BridgeId,
  val raw_battery_Id : Art.PortId,
  val battery_assessment_Id : Art.PortId) extends Battery_Assessment_Api

@datatype class Battery_Assessment_Operational_Api (
  val id: Art.BridgeId,
  val raw_battery_Id : Art.PortId,
  val battery_assessment_Id : Art.PortId) extends Battery_Assessment_Api {

  // Logika spec var representing port state for incoming data port
  @spec var raw_battery: Drone_Lifecycle_Governor.Battery_Sample = $

  def get_raw_battery() : Option[Drone_Lifecycle_Governor.Battery_Sample] = {
    Contract(
      Ensures(
        Res == Some(raw_battery)
      )
    )
    val value : Option[Drone_Lifecycle_Governor.Battery_Sample] = Art.getValue(raw_battery_Id) match {
      case Some(Drone_Lifecycle_Governor.Battery_Sample_Payload(v)) => Some(v)
      case Some(v) =>
        Art.logError(id, s"Unexpected payload on port raw_battery.  Expecting 'Drone_Lifecycle_Governor.Battery_Sample_Payload' but received ${v}")
        None[Drone_Lifecycle_Governor.Battery_Sample]()
      case _ => None[Drone_Lifecycle_Governor.Battery_Sample]()
    }
    return value
  }
}
